package auronq

const explorerIndexHTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>AuronQ Explorer</title>\n<style>\n:root{--bg:#070b12;--panel:#0f1724;--line:#22334d;--text:#edf4ff;--muted:#8fa2ba;--green:#68e2b7;--blue:#66a6ff;--red:#ff8796}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,rgba(102,166,255,.13),transparent 35%),var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}\n.wrap{max-width:1180px;margin:auto;padding:28px 18px 60px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:22px;font-weight:800}.brand span{color:var(--green)}.sub{color:var(--muted);font-size:12px}\n.search{display:flex;gap:8px;margin:24px 0}.search input{flex:1;background:#08111b;border:1px solid var(--line);color:var(--text);border-radius:12px;padding:13px}.search button{border:0;border-radius:12px;padding:0 18px;font-weight:800;background:linear-gradient(135deg,var(--green),var(--blue));color:#06110f;cursor:pointer}\n.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card,.panel{background:linear-gradient(180deg,#121c2b,#0c141f);border:1px solid var(--line);border-radius:16px;padding:16px}.label{font-size:11px;color:var(--muted)}.value{font-size:20px;font-weight:800;margin-top:6px}.panel{margin-top:16px}.panel h2{font-size:16px;margin:0 0 12px}\ntable{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid var(--line);font-size:12px}th{color:var(--muted)}a{color:var(--blue);cursor:pointer;text-decoration:none}.mono{font-family:ui-monospace,Consolas,monospace;word-break:break-all}.muted{color:var(--muted)}.ok{color:var(--green)}.bad{color:var(--red)}.pill{display:inline-block;padding:3px 8px;border-radius:999px;background:#172338;color:var(--muted);font-size:10px}.detail{display:grid;grid-template-columns:160px 1fr;gap:8px 14px}.detail div:nth-child(odd){color:var(--muted)}.io{display:grid;grid-template-columns:1fr 1fr;gap:12px}.io .card{padding:12px}.hidden{display:none}\n@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.io{grid-template-columns:1fr}}@media(max-width:560px){.grid{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.detail{grid-template-columns:1fr}.search{flex-direction:column}.search button{padding:12px}}\n</style>\n</head>\n<body><div class=\"wrap\">\n<div class=\"top\"><div><div class=\"brand\"><span>AuronQ</span> Explorer</div><div class=\"sub\">AURQ Mainnet \u2022 read-only blockchain explorer</div></div><div id=\"live\" class=\"pill\">connecting\u2026</div></div>\n<form class=\"search\" id=\"search\"><input id=\"q\" autocomplete=\"off\" placeholder=\"Search address, transaction ID, block height or block hash\"><button>Search</button></form>\n<div class=\"grid\">\n<div class=\"card\"><div class=\"label\">Height</div><div class=\"value\" id=\"height\">\u2014</div></div>\n<div class=\"card\"><div class=\"label\">Network power (est.)</div><div class=\"value\" id=\"power\">\u2014</div></div>\n<div class=\"card\"><div class=\"label\">Peers</div><div class=\"value\" id=\"peers\">\u2014</div></div>\n<div class=\"card\"><div class=\"label\">Mempool</div><div class=\"value\" id=\"mempool\">\u2014</div></div>\n<div class=\"card\"><div class=\"label\">Issued supply</div><div class=\"value\" id=\"issued\">\u2014</div></div>\n</div>\n<div id=\"result\" class=\"panel hidden\"></div>\n<div class=\"panel\"><h2>Latest blocks</h2><div style=\"overflow:auto\"><table><thead><tr><th>Height</th><th>Hash</th><th>Time</th><th>Txs</th><th>Size</th></tr></thead><tbody id=\"blocks\"></tbody></table></div></div>\n</div>\n<script>\nconst $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst short=(s,n=10)=>s?String(s).slice(0,n)+'\u2026'+String(s).slice(-n):'\u2014';\nconst num=n=>Number(n||0).toLocaleString();\nfunction hashFmt(v){v=Number(v||0);const u=['H/s','kH/s','MH/s','GH/s','TH/s'];let i=0;while(v>=1000&&i<u.length-1){v/=1000;i++}return (v>=100?v.toFixed(0):v>=10?v.toFixed(1):v.toFixed(2))+' '+u[i]}\nfunction when(ts){if(!ts)return '\u2014';return new Date(ts*1000).toLocaleString()}\nasync function get(url){const r=await fetch(url,{cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j}\nasync function refresh(){\n try{\n  const [s,b]=await Promise.all([get('/v1/status'),get('/v1/explorer/blocks?limit=20')]);\n  $('height').textContent=num(s.height);$('power').textContent=hashFmt(s.network_hashrate);$('peers').textContent=num(s.peers);$('mempool').textContent=num(s.mempool);$('issued').textContent=Number(s.issued_coins||0).toLocaleString(undefined,{maximumFractionDigits:8})+' AURQ';\n  $('live').textContent='local full node verified';$('live').className='pill ok';\n  $('blocks').innerHTML=b.blocks.map(x=>'<tr><td><a onclick=\"showBlock('+x.height+')\">'+num(x.height)+'</a></td><td class=\"mono\"><a onclick=\"showBlockHash(\\''+esc(x.hash)+'\\')\">'+short(x.hash,8)+'</a></td><td>'+when(x.timestamp)+'</td><td>'+num(x.transactions)+'</td><td>'+num(x.size)+' B</td></tr>').join('');\n }catch(e){$('live').textContent='node unavailable';$('live').className='pill bad'}\n}\nfunction show(html){$('result').innerHTML=html;$('result').classList.remove('hidden');$('result').scrollIntoView({behavior:'smooth',block:'start'})}\nasync function showBlock(h){try{const x=await get('/v1/explorer/block?height='+encodeURIComponent(h));renderBlock(x)}catch(e){show('<h2>Block</h2><div class=\"bad\">'+esc(e.message)+'</div>')}}\nasync function showBlockHash(h){try{const x=await get('/v1/explorer/block?hash='+encodeURIComponent(h));renderBlock(x)}catch(e){show('<h2>Block</h2><div class=\"bad\">'+esc(e.message)+'</div>')}}\nfunction renderBlock(x){const s=x.summary;show('<h2>Block #'+num(s.height)+'</h2><div class=\"detail\"><div>Hash</div><div class=\"mono\">'+esc(s.hash)+'</div><div>Previous</div><div class=\"mono\">'+esc(s.prev_hash)+'</div><div>Time</div><div>'+when(s.timestamp)+'</div><div>Transactions</div><div>'+num(s.transactions)+'</div><div>Size</div><div>'+num(s.size)+' B</div><div>Nonce</div><div>'+num(x.nonce)+'</div><div>Target</div><div class=\"mono\">'+esc(s.target)+'</div><div>Merkle root</div><div class=\"mono\">'+esc(x.merkle_root)+'</div></div><h2 style=\"margin-top:18px\">Transactions</h2>'+x.transactions.map(id=>'<div class=\"mono\" style=\"padding:7px 0\"><a onclick=\"showTx(\\''+esc(id)+'\\')\">'+esc(id)+'</a></div>').join(''))}\nasync function showTx(id){try{const x=await get('/v1/explorer/tx?txid='+encodeURIComponent(id));renderTx(x)}catch(e){show('<h2>Transaction</h2><div class=\"bad\">'+esc(e.message)+'</div>')}}\nfunction renderTx(x){const ins=x.inputs.length?x.inputs.map(i=>'<div class=\"card\"><div class=\"mono\"><a onclick=\"showTx(\\''+esc(i.prev_tx)+'\\')\">'+short(i.prev_tx,10)+':'+i.prev_index+'</a></div><div>'+esc(i.value||'unknown')+' AURQ</div><div class=\"mono muted\">'+esc(i.address||'unresolved')+'</div></div>').join(''):'<div class=\"card muted\">Coinbase transaction</div>';const outs=x.outputs.map(o=>'<div class=\"card\"><div><b>'+esc(o.value)+' AURQ</b></div><div class=\"mono\"><a onclick=\"showAddress(\\''+esc(o.address)+'\\')\">'+esc(o.address)+'</a></div></div>').join('');show('<h2>Transaction</h2><div class=\"detail\"><div>TXID</div><div class=\"mono\">'+esc(x.txid)+'</div><div>Status</div><div>'+esc(x.status)+' \u2022 '+num(x.confirmations)+' confirmations</div><div>Block</div><div>'+(x.height==null?'mempool':'<a onclick=\"showBlock('+x.height+')\">#'+num(x.height)+'</a>')+'</div><div>Time</div><div>'+when(x.timestamp)+'</div><div>Fee</div><div>'+esc(x.fee)+' AURQ</div><div>Size</div><div>'+num(x.size)+' B</div></div><div class=\"io\" style=\"margin-top:18px\"><div><h2>Inputs</h2>'+ins+'</div><div><h2>Outputs</h2>'+outs+'</div></div>')}\nasync function showAddress(a){try{const [b,h]=await Promise.all([get('/v1/balance?address='+encodeURIComponent(a)),get('/v1/history?address='+encodeURIComponent(a)+'&limit=50')]);show('<h2>Address</h2><div class=\"mono\">'+esc(a)+'</div><div class=\"grid\" style=\"margin-top:14px\"><div class=\"card\"><div class=\"label\">Spendable</div><div class=\"value\">'+(Number(b.spendable)/1e8).toFixed(8)+' AURQ</div></div><div class=\"card\"><div class=\"label\">Total</div><div class=\"value\">'+(Number(b.total)/1e8).toFixed(8)+' AURQ</div></div></div><h2 style=\"margin-top:18px\">History</h2><div style=\"overflow:auto\"><table><thead><tr><th>Type</th><th>TXID</th><th>Amount</th><th>Status</th><th>Block</th></tr></thead><tbody>'+h.items.map(x=>'<tr><td>'+esc(x.type)+'</td><td class=\"mono\"><a onclick=\"showTx(\\''+esc(x.txid)+'\\')\">'+short(x.txid,8)+'</a></td><td>'+esc(x.net)+' AURQ</td><td>'+esc(x.status)+'</td><td>'+(x.height==null?'\u2014':'<a onclick=\"showBlock('+x.height+')\">#'+num(x.height)+'</a>')+'</td></tr>').join('')+'</tbody></table></div>')}catch(e){show('<h2>Address</h2><div class=\"bad\">'+esc(e.message)+'</div>')}}\n$('search').addEventListener('submit',async e=>{e.preventDefault();const q=$('q').value.trim();if(!q)return;if(/^aurq1/i.test(q))return showAddress(q);if(/^\\d+$/.test(q))return showBlock(Number(q));if(/^[0-9a-f]{128}$/i.test(q)){try{const x=await get('/v1/explorer/tx?txid='+encodeURIComponent(q));return renderTx(x)}catch(_){return showBlockHash(q)}}show('<h2>Search</h2><div class=\"bad\">Unrecognized AuronQ identifier.</div>')});\nrefresh();setInterval(refresh,10000);\n</script></body></html>"
